"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1520],{1520:a=>{a.exports=JSON.parse('{"slug":"sankcii-ssha-platezhnaya-set-a7","locale":"es","title":"Estados Unidos propone prohibir transferencias bancarias mediante cientos de empresas de A7","description":"El Tesoro declar\xf3 a A7 organizaci\xf3n criminal el 1 de octubre y propuso bloquear pagos mediante sus subagentes. C\xf3mo afecta a las importaciones.","blocks":[{"id":"b001","kind":"paragraph","text":"El Tesoro estadounidense declar\xf3 el 1 de octubre de 2026 a la red rusa A7 una \xaborganizaci\xf3n criminal transnacional significativa\xbb. FinCEN, su unidad contra delitos financieros, propuso adem\xe1s prohibir a los bancos estadounidenses cualquier transferencia mediante los \xabsubagentes\xbb de A7: empresas pantalla extranjeras usadas para pagar por clientes rusos."},{"id":"b002","kind":"paragraph","text":"Ilan Shor y Promsvyazbank lanzaron A7 en 2024. Cobra un 0,3% y emite A7A5, una moneda digital estable vinculada al rublo. La parte rusa de A7 y su moneda est\xe1n sancionadas desde agosto de 2025, pero los pagos segu\xedan mediante firmas extranjeras. Estados Unidos vincula la red con el banco central iran\xed y la Guardia Revolucionaria. FinCEN fundamenta su propuesta en la ley contra el blanqueo de dinero ruso."},{"id":"b003","kind":"paragraph","text":"A7 tiene cientos de subagentes en Emiratos, Hong Kong, Turqu\xeda, Kirguist\xe1n y otros pa\xedses, con cuentas en unos 435 bancos de 83 pa\xedses. Entre enero de 2025 y junio de 2026 movieron m\xe1s de $17 mil millones en d\xf3lares, solo una parte del total: en enero de 2026 declaraba 7,5 billones de rublos hist\xf3ricos. Promsvyazbank estimaba que A7 canaliz\xf3 casi el 12% del comercio exterior ruso en el primer semestre de 2025. FinCEN cita casi el 13% para todo 2025."},{"id":"b004","kind":"paragraph","text":"Estados Unidos puede frenar pagos ajenos porque una transferencia internacional en d\xf3lares casi siempre cruza una cuenta estadounidense. Como un paquete que debe pasar por un centro de clasificaci\xf3n: si lo rechaza, no llega aunque ambos extremos est\xe9n fuera. Es una cuenta corresponsal. La prohibici\xf3n corta ese acceso a los subagentes de A7. Puede afectar a otras monedas: los bancos extranjeros con sus cuentas temen sanciones propias y podr\xedan cerrarlas en cualquier divisa. La lista de firmas se distribuir\xe1 de forma confidencial y se actualizar\xe1."},{"id":"b005","kind":"paragraph","text":"Las sanciones contra A7 no afectan directamente al bolsillo personal: la red sirve a empresas. Llegan por los precios importados. Cada barrera vuelve el pago exterior m\xe1s lento y caro, y la empresa traslada el coste al producto. No puede estimarse la subida. A7 ya fue sancionada en 2025 y sigui\xf3 operando mediante nuevas firmas."},{"id":"b006","kind":"paragraph","text":"La regla de FinCEN a\xfan es una propuesta, con 30 d\xedas de comentarios tras publicarse. El Tesoro espera que otros pa\xedses y bancos lo sigan, pero no se sabe si lo har\xe1n. No es motivo para acumular aparatos o repuestos: el efecto tardar\xe1 meses y se mezclar\xe1 con el rublo. Tampoco conviene ignorarlo: los pagos caros acaban en el precio final."},{"id":"b007","kind":"heading","text":"\xbfQu\xe9 es A7?"},{"id":"b008","kind":"paragraph","text":"Una red internacional creada en 2024 por Ilan Shor y Promsvyazbank. Mueve pagos de empresas rusas mediante sociedades pantalla extranjeras, cobra el 0,3% y emite la moneda estable en rublos A7A5."},{"id":"b009","kind":"heading","text":"\xbfQu\xe9 medidas tom\xf3 Estados Unidos contra A7 en octubre de 2026?"},{"id":"b010","kind":"paragraph","text":"El 1 de octubre de 2026, el Tesoro declar\xf3 a A7 organizaci\xf3n criminal transnacional. FinCEN propuso prohibir pagos bancarios estadounidenses mediante cientos de subagentes con cuentas en unos 435 bancos de 83 pa\xedses."},{"id":"b011","kind":"heading","text":"\xbfSe encarecer\xe1 la importaci\xf3n por A7?"},{"id":"b012","kind":"paragraph","text":"Es posible, sin una magnitud conocida. A7 canalizaba casi el 12–13% del comercio exterior ruso; cada obst\xe1culo ralentiza y encarece los pagos y las empresas trasladan el coste al producto."}],"sources":[{"label":"Estados Unidos sanciona al sistema de pagos A7","url":"https://www.kommersant.ru/doc/8991793"},{"label":"Estados Unidos prepara el bloqueo de pagos de cientos de firmas extranjeras de A7","url":"https://thebell.io/ssha-gotovyat-zapret-na-platezhi-cherez-sotni-zarubezhnykh-kompaniy-a7-po-otsenke-psb-cherez-etu-set-shlo-pochti-12-vneshney-torgovli-rossii"},{"label":"Propuesta de medida especial sobre subagentes de A7","url":"https://www.fincen.gov/system/files/2026-10/9714-A7-NETWORK-NPRM.pdf"}],"sourceBodySha256":"e928692ceb98a757973abed5533e72f30df7536893758054b08fc807c779360a"}')}}]);